"""Browser-side optional sound control for NTIS SDL B4.2."""
from __future__ import annotations
from dataclasses import dataclass
from html import escape
import json

_SOUND_DATA = {
    "soft": "data:audio/wav;base64,",
    "single": "data:audio/wav;base64,",
    "double": "data:audio/wav;base64,",
}

@dataclass(frozen=True)
class SoundSettings:
    enabled: bool = False
    volume: float = 0.35
    tone: str = "soft"
    def normalized(self) -> "SoundSettings":
        return SoundSettings(bool(self.enabled), max(0.0,min(1.0,float(self.volume))), self.tone if self.tone in _SOUND_DATA else "soft")

def sound_html(settings: SoundSettings, trigger: bool=False, nonce: str="sdl") -> str:
    s=settings.normalized()
    vol=f"{s.volume:.3f}"
    tone=escape(s.tone)
    trigger_js="true" if trigger else "false"
    enabled_js="true" if s.enabled else "false"
    data_json=json.dumps(_SOUND_DATA, separators=(",",":"))
    return f"""
<div id="{escape(nonce)}" style="display:flex;align-items:center;gap:8px;font-family:Arial,sans-serif">
  <button id="{escape(nonce)}-test" type="button" style="height:30px;padding:0 10px;border:1px solid #315277;border-radius:6px;background:#0d1b2e;color:#eaf2fb;cursor:pointer;font-size:11px">▶ Test Sound</button>
  <span id="{escape(nonce)}-status" style="font-size:9px;color:#8fa5c0">Click Test Sound to enable browser audio</span>
</div>
<script>
(function(){{
 const btn=document.getElementById('{escape(nonce)}-test'),status=document.getElementById('{escape(nonce)}-status');
 const volume={vol},tone='{tone}',trigger={trigger_js},enabled={enabled_js},sounds={data_json};
 function setStatus(t,c){{status.textContent=t;status.style.color=c||'#8fa5c0';}}
 async function playAudio(){{
   try{{
     const a=new Audio(sounds[tone]); a.volume=volume; a.preload='auto';
     const p=a.play(); if(p && p.then) await p;
     setStatus('Audio ready','#18df82'); return true;
   }}catch(e){{
     try{{
       const C=window.AudioContext||window.webkitAudioContext; if(!C) throw e;
       const c=new C(); if(c.state==='suspended') await c.resume();
       const o=c.createOscillator(),g=c.createGain(); o.type='sine'; o.frequency.value=tone==='single'?740:520;
       const now=c.currentTime; g.gain.setValueAtTime(0,now); g.gain.linearRampToValueAtTime(volume*0.12,now+0.015); g.gain.exponentialRampToValueAtTime(0.001,now+0.11); o.connect(g);g.connect(c.destination);o.start(now);o.stop(now+0.12);
       setStatus('Audio ready','#18df82'); return true;
     }}catch(e2){{ setStatus('Browser blocked audio','#ffb21c'); return false; }}
   }}
 }}
 btn.addEventListener('click',async function(){{ try{{localStorage.setItem('sdl_b4_audio_unlocked','1');}}catch(e){{}} await playAudio(); }});
 if(trigger && enabled){{ let unlocked=false; try{{unlocked=localStorage.getItem('sdl_b4_audio_unlocked')==='1';}}catch(e){{}} if(unlocked) setTimeout(()=>playAudio(),40); else setStatus('Sound armed; click Test Sound once','#ffb21c'); }}
}})();
</script>
"""
